/// GML: `oGame/draw#2`.
pub fn draw_a2(g: &mut World, cx: &mut Ctx) -> R<()> {
    // 4: if (false && room == rLevel)
    g.at("oGame/draw#2", 4);
    if and(r(0.0).is_truthy(), g.bget(v::room, 0)?.gml_eq(&rm::rLevel)?) {
        // 6: for (...; j < 4; ...)
        g.at("oGame/draw#2", 6);
        // 6: j = 0;
        g.at("oGame/draw#2", 6);
        g.set(cx.this, v::j, r(0.0))?;
        'for1: loop {
            if !(g.get(cx.this, v::j)?.gml_lt(&r(4.0))?) { break 'for1; }
            'body2: {
                // 8: for (...; i < 4; ...)
                g.at("oGame/draw#2", 8);
                // 8: i = 0;
                g.at("oGame/draw#2", 8);
                g.set(cx.this, v::i, r(0.0))?;
                'for3: loop {
                    if !(g.get(cx.this, v::i)?.gml_lt(&r(4.0))?) { break 'for3; }
                    'body4: {
                        // 10: draw_text(oPlayer1.x + 48 + i * 16, oPlayer1.y - 64 + 16 + j * 16, string(global.roomPath[i, j]));
                        g.at("oGame/draw#2", 10);
                        { let a = [g.get_on(cx, &obj::oPlayer1, v::x)?.add(&r(48.0))?.add(&g.get(cx.this, v::i)?.mul(&r(16.0))?)?, g.get_on(cx, &obj::oPlayer1, v::y)?.sub(&r(64.0))?.add(&r(16.0))?.add(&g.get(cx.this, v::j)?.mul(&r(16.0))?)?, { let a = [g.gget_a(gv::roomPath, ix(&g.get(cx.this, v::i)?)?, ix(&g.get(cx.this, v::j)?)?)?]; b::string(g, cx, a)? }]; b::draw_text(g, cx, a)? };
                    }
                    // 8: i += 1;
                    g.at("oGame/draw#2", 8);
                    g.set(cx.this, v::i, lenient(Value::add, g.get(cx.this, v::i)?, &r(1.0)))?;
                }
            }
            // 6: j += 1;
            g.at("oGame/draw#2", 6);
            g.set(cx.this, v::j, lenient(Value::add, g.get(cx.this, v::j)?, &r(1.0)))?;
        }
    }
    // 15: if (false && instance_exists(oPlayer1))
    g.at("oGame/draw#2", 15);
    if and(r(0.0).is_truthy(), b::instance_exists(g, cx, [obj::oPlayer1])?.is_truthy()) {
        // 17: file = file_text_open_read("stats.txt");
        g.at("oGame/draw#2", 17);
        { let x = b::file_text_open_read(g, cx, [s!("stats.txt")])?; g.set(cx.this, v::file, x)?; }
        // 19: if (file)
        g.at("oGame/draw#2", 19);
        if g.get(cx.this, v::file)?.is_truthy() {
            // 21: file_text_readln(file);
            g.at("oGame/draw#2", 21);
            { let a = [g.get(cx.this, v::file)?]; b::file_text_readln(g, cx, a)? };
            // 22: file_text_readln(file);
            g.at("oGame/draw#2", 22);
            { let a = [g.get(cx.this, v::file)?]; b::file_text_readln(g, cx, a)? };
            // 23: file_text_readln(file);
            g.at("oGame/draw#2", 23);
            { let a = [g.get(cx.this, v::file)?]; b::file_text_readln(g, cx, a)? };
            // 24: file_text_readln(file);
            g.at("oGame/draw#2", 24);
            { let a = [g.get(cx.this, v::file)?]; b::file_text_readln(g, cx, a)? };
            // 25: str = file_text_read_string(file);
            g.at("oGame/draw#2", 25);
            {
                let x = { let a = [g.get(cx.this, v::file)?]; b::file_text_read_string(g, cx, a)? };
                g.set(cx.this, v::str, x)?;
            }
            // 26: str = string_delete(str, 1, 20);
            g.at("oGame/draw#2", 26);
            {
                let x = { let a = [g.get(cx.this, v::str)?, r(1.0), r(20.0)]; b::string_delete(g, cx, a)? };
                g.set(cx.this, v::str, x)?;
            }
            // 27: global.totalCrates = real(str);
            g.at("oGame/draw#2", 27);
            { let x = { let a = [g.get(cx.this, v::str)?]; b::real(g, cx, a)? }; g.gset(gv::totalCrates, x)?; }
            // 28: file_text_readln(file);
            g.at("oGame/draw#2", 28);
            { let a = [g.get(cx.this, v::file)?]; b::file_text_readln(g, cx, a)? };
            // 29: str = file_text_read_string(file);
            g.at("oGame/draw#2", 29);
            {
                let x = { let a = [g.get(cx.this, v::file)?]; b::file_text_read_string(g, cx, a)? };
                g.set(cx.this, v::str, x)?;
            }
            // 33: draw_text(oPlayer1.x + 16, oPlayer1.y - 16, str);
            g.at("oGame/draw#2", 33);
            { let a = [g.get_on(cx, &obj::oPlayer1, v::x)?.add(&r(16.0))?, g.get_on(cx, &obj::oPlayer1, v::y)?.sub(&r(16.0))?, g.get(cx.this, v::str)?]; b::draw_text(g, cx, a)? };
            // 35: file_text_close(file);
            g.at("oGame/draw#2", 35);
            { let a = [g.get(cx.this, v::file)?]; b::file_text_close(g, cx, a)? };
        }
    }
    // 39: if (false && instance_exists(oPlayer1))
    g.at("oGame/draw#2", 39);
    if and(r(0.0).is_truthy(), b::instance_exists(g, cx, [obj::oPlayer1])?.is_truthy()) {
        // 41: draw_set_font(global.myFontSmall);
        g.at("oGame/draw#2", 41);
        { let a = [g.gget(gv::myFontSmall)?]; b::draw_set_font(g, cx, a)? };
        // 42: draw_set_color(c_white);
        g.at("oGame/draw#2", 42);
        b::draw_set_color(g, cx, [k::c_white])?;
        // 43: draw_text(oPlayer1.x + 16, oPlayer1.y - 16, string(oPlayer1.stunTimer));
        g.at("oGame/draw#2", 43);
        { let a = [g.get_on(cx, &obj::oPlayer1, v::x)?.add(&r(16.0))?, g.get_on(cx, &obj::oPlayer1, v::y)?.sub(&r(16.0))?, { let a = [g.get_on(cx, &obj::oPlayer1, v::stunTimer)?]; b::string(g, cx, a)? }]; b::draw_text(g, cx, a)? };
    }
    Ok(())
}

/// GML: `oGame/draw#4`.
pub fn draw_a4(g: &mut World, cx: &mut Ctx) -> R<()> {
    // 5: if (false && room == rLevel && instance_exists(oXMarket))
    g.at("oGame/draw#4", 5);
    if and(and(r(0.0).is_truthy(), g.bget(v::room, 0)?.gml_eq(&rm::rLevel)?), b::instance_exists(g, cx, [obj::oXMarket])?.is_truthy()) {
        // 7: draw_text(oPlayer1.x - 24, oPlayer1.y - 48, string(oPlayer1.x - oXMarket.x));
        g.at("oGame/draw#4", 7);
        { let a = [g.get_on(cx, &obj::oPlayer1, v::x)?.sub(&r(24.0))?, g.get_on(cx, &obj::oPlayer1, v::y)?.sub(&r(48.0))?, { let a = [g.get_on(cx, &obj::oPlayer1, v::x)?.sub(&g.get_on(cx, &obj::oXMarket, v::x)?)?]; b::string(g, cx, a)? }]; b::draw_text(g, cx, a)? };
        // 8: draw_text(oPlayer1.x, oPlayer1.y - 48, string(oPlayer1.y - oXMarket.y));
        g.at("oGame/draw#4", 8);
        { let a = [g.get_on(cx, &obj::oPlayer1, v::x)?, g.get_on(cx, &obj::oPlayer1, v::y)?.sub(&r(48.0))?, { let a = [g.get_on(cx, &obj::oPlayer1, v::y)?.sub(&g.get_on(cx, &obj::oXMarket, v::y)?)?]; b::string(g, cx, a)? }]; b::draw_text(g, cx, a)? };
    }
    Ok(())
}

/// GML: `oGame/keypress_77#0`.
pub fn keypress_77_a0(g: &mut World, cx: &mut Ctx) -> R<()> {
    // 1: if (global.music)
    g.at("oGame/keypress_77#0", 1);
    if g.gget(gv::music)?.is_truthy() {
        // 3: global.music = false;
        g.at("oGame/keypress_77#0", 3);
        g.gset(gv::music, r(0.0))?;
        // 4: stopAllMusic();
        g.at("oGame/keypress_77#0", 4);
        scr::stopAllMusic(g, cx, &[])?;
    } else {
        // 8: global.music = true;
        g.at("oGame/keypress_77#0", 8);
        g.gset(gv::music, r(1.0))?;
        // 9: if (isLevel())
        g.at("oGame/keypress_77#0", 9);
        if scr::isLevel(g, cx, &[])?.is_truthy() {
            // 11: if (global.levelType == 1)
            g.at("oGame/keypress_77#0", 11);
            if g.gget(gv::levelType)?.gml_eq(&r(1.0))? {
                // 11: playMusic(global.musLush, true);
                g.at("oGame/keypress_77#0", 11);
                { let a = [g.gget(gv::musLush)?, r(1.0)]; scr::playMusic(g, cx, &a)? };
            } else {
                // 12: if (global.levelType == 2)
                g.at("oGame/keypress_77#0", 12);
                if g.gget(gv::levelType)?.gml_eq(&r(2.0))? {
                    // 12: playMusic(global.musIce, true);
                    g.at("oGame/keypress_77#0", 12);
                    { let a = [g.gget(gv::musIce)?, r(1.0)]; scr::playMusic(g, cx, &a)? };
                } else {
                    // 13: if (global.levelType == 3)
                    g.at("oGame/keypress_77#0", 13);
                    if g.gget(gv::levelType)?.gml_eq(&r(3.0))? {
                        // 13: playMusic(global.musTemple, true);
                        g.at("oGame/keypress_77#0", 13);
                        { let a = [g.gget(gv::musTemple)?, r(1.0)]; scr::playMusic(g, cx, &a)? };
                    } else {
                        // 14: if (isRoom("rOlmec"))
                        g.at("oGame/keypress_77#0", 14);
                        if scr::isRoom(g, cx, &[s!("rOlmec")])?.is_truthy() {
                            // 16: if (oPlayer1.active)
                            g.at("oGame/keypress_77#0", 16);
                            if g.get_on(cx, &obj::oPlayer1, v::active)?.is_truthy() {
                                // 17: playMusic(global.musBoss, true);
                                g.at("oGame/keypress_77#0", 17);
                                { let a = [g.gget(gv::musBoss)?, r(1.0)]; scr::playMusic(g, cx, &a)? };
                            }
                        } else {
                            // 19: playMusic(global.musCave, true);
                            g.at("oGame/keypress_77#0", 19);
                            { let a = [g.gget(gv::musCave)?, r(1.0)]; scr::playMusic(g, cx, &a)? };
                        }
                    }
                }
            }
        } else {
            // 21: if (isRoom("rTitle"))
            g.at("oGame/keypress_77#0", 21);
            if scr::isRoom(g, cx, &[s!("rTitle")])?.is_truthy() {
                // 21: playMusic(global.musTitle, true);
                g.at("oGame/keypress_77#0", 21);
                { let a = [g.gget(gv::musTitle)?, r(1.0)]; scr::playMusic(g, cx, &a)? };
            }
        }
    }
    Ok(())
}

